import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './App.css';
import Login from './login'; // Import the Login component
import { Button } from '@mui/material'; 

function App() {
    const [data, setData] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [isLoggedIn, setIsLoggedIn] = useState(false); // Track login status
    const [userRole, setUserRole] = useState(null); // Track user role

    useEffect(() => {
        const fetchData = async () => {
            try {
                const response = await axios.get('http://localhost:5000/api/data'); // Full URL
                setData(response.data);
                const token = localStorage.getItem('token');
                const storedRole = localStorage.getItem('role'); // Get role from storage
                setIsLoggedIn(!!token);
                setUserRole(storedRole); // Set the user role
            } catch (err) {
                setError(err);
            } finally {
                setLoading(false);
            }
        };
        fetchData();
    }, []);

    const handleLogout = () => {
        localStorage.removeItem('token');
        localStorage.removeItem('username');
        localStorage.removeItem('role'); // Clear role on logout
        setIsLoggedIn(false);
        setUserRole(null); // Reset role
        window.location.href = '/';
    };

    useEffect(() => {
        if (isLoggedIn) {
            // Redirect based on user role
            if (userRole === 'admin') {
                window.location.href = '/admin-home'; // Redirect to admin home
            } else {
                window.location.href = '/user-home'; // Redirect to user home
            }
        }
    }, [isLoggedIn, userRole]); // Redirect when logged in or role changes

    if (loading) {
        return <div>Loading...</div>;
    }

    if (error) {
        return <div>Error: {error.message}</div>;
    }

    if (!isLoggedIn) {
        return (
            <div className="App">
                <Login /> {/* Render the Login component */}
            </div>
        );
    }

    //moved theিলোgic
    return (
        <div className="App">
            <header className="App-header">
                {data ? (
                    <>
                        <p>{data.message}</p>
                        <p>Welcome, {localStorage.getItem('username')}!</p>
                        <Button onClick={handleLogout} variant="contained" color="primary">Logout</Button>
                    </>
                ) : (
                    <p>No data received from the backend.</p>
                )}
            </header>
        </div>
    );
}

export default App;
